          "easy1_desc": "코로나19가 지나간 뒤에 OTT(온라인 동영상 서비스)가 늘어나고 영화관 표 값도 오르면서 극장을 찾는 사람이 줄어들었다고 해요. 게다가 사람들이 영화를 보는 방식도 개인화되면서 영화 산업 전체의 수익성이 나빠진 상황인데요. 쉽게 말하면, 예전처럼 영화관을 찾는 수요가 줄어들면서 산업 자체가 위축되었다는 말이에요.",
