          "easy1_desc": "AI 산업이 커지면서 데이터를 써야 할 곳은 많은데, 지금의 규제는 법으로 허용해도 실제 활용까지 가기가 어렵다는 지적이 나왔거든요. 데이터 보호와 활용을 동시에 하려다 보니 검토 단계가 너무 겹쳐서 현장에서 느끼는 부담이 크다는 말이에요. 그래서 법적 허용이 실제 활용과 보호로 이어지도록 판단 기준과 책임 체계를 다시 정비해야 한다는 겁니다.",
