          "source_name": "네이버 리서치 산업",
          "kind": "증권사 리포트",
          "writer": "키움증권",
          "title": "[키움증권]  이차전지 2027년 연간 전망: 실적 저점을 통과하는 구간, 점차 개선되는 지표들",
          "easy1_title": "이차전지 실적이 이제 바닥을 찍고 올라올 때가 됐어요",
          "easy1_desc": "그동안 전기차 판매가 주춤하면서 이차전지 업체들의 실적이 꽤 부진했는데요. 이제는 실적이 바닥을 통과하고 있어서 2027년에는 주요 기업들이 대부분 분기 흑자로 돌아설 것으로 보입니다. 전기차 수요가 완전히 살아난 건 아니지만, 더 나빠질 곳은 없다는 뜻이에요. 쉽게 말하면 이제는 실적이 좋아질 일만 남았다는 겁니다.",
          "easy2_title": "전기차보다 ESS가 실적을 이끄는 효자 노릇을 할 겁니다",
          "easy2_desc": "전기차 부문은 아직 회복이 더디지만, 대신 에너지저장장치인 ESS 사업이 아주 빠르게 성장하고 있는데요. 특히 미국에서 AI 데이터센터 전력 수요가 늘면서 ESS 설치가 역대급으로 많아지고 있어요. 2027년부터는 ESS가 매출뿐만 아니라 이익까지 든든하게 채워줄 것으로 보입니다. 쉽게 말하면 전기차의 빈자리를 ESS가 확실하게 메워주고 있다는 말이에요.",
          "topic": "이차전지 산업이 실적 저점을 지나 2027년부터는 본격적인 회복 국면에 들어설 것으로 증권사는 전망했습니다.",
          "points": [
            "실적 회복과 밸류에이션 재평가: 증권사는 2027년 이차전지 산업이 실적 검증을 거쳐 회복 단계로 진입할 것으로 봤는데요. 주가는 보통 6개월 정도 앞서 움직이는 특성이 있어서, 2027년 상반기부터는 주가에 이런 기대감이 먼저 반영될 것으로 보입니다.",
            "ESS 사업의 구조적 성장: 미국 ESS 시장은 단순히 재생에너지를 저장하는 것을 넘어 AI 데이터센터 전력 공급이라는 새로운 수요가 더해지고 있는데요. 2027년 미국 BESS 설치 수요는 88GWh로 전년 대비 26% 성장할 것으로 추정됩니다.",
            "공급망 재편과 국내 업체의 기회: 중국산 배터리에 대한 관세 부과와 미국 내 공급망 안보 정책이 강화되면서 국내 업체들에게 우호적인 환경이 만들어지고 있는데요. 북미 생산 기반을 갖춘 국내 셀 업체들의 점유율이 구조적으로 확대될 것으로 증권사는 분석했습니다."
          ],
          "evidence_ok": "6/6",
          "bad_numbers": "",
          "check_flags": "예측 의심: 이제는 실적이 바닥을 통과하고 있어서 2027년에는 주요 기업들이 대부분 분기 흑자로 돌아설 것으로 보입니다; 예측 의심: 2027년부터는 ESS가 매출뿐만 아니라 이익까지 든든하게 채워줄 것으로 보입니다.; 예측 의심: 주가는 보통 6개월 정도 앞서 움직이는 특성이 있어서, 2027년 상반기부터는 주가에 이런 기대감이 먼저 반; 긴 원문 — 앞 30000자만 읽음(전체 131921자)",
